-- Post-apply RLS and grant verification. READ ONLY. One 'label|t/f' row per check; every row must be t.
-- Covers every table, view, sequence and function in rtgip, rtgip_src and rtgip_fx (not just the known list) and the package's
-- public tables and functions. Vacuously true for a schema that is not installed.
SELECT 'anon_has_no_privilege_on_rtgip_tables|' || CASE WHEN NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace, LATERAL (VALUES ('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) pv(p) WHERE n.nspname IN ('rtgip','rtgip_src','rtgip_fx') AND c.relkind IN ('r','p') AND has_table_privilege('anon', c.oid, pv.p)) THEN 't' ELSE 'f' END
UNION ALL
SELECT 'authenticated_has_no_privilege_on_rtgip_tables|' || CASE WHEN NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace, LATERAL (VALUES ('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) pv(p) WHERE n.nspname IN ('rtgip','rtgip_src','rtgip_fx') AND c.relkind IN ('r','p') AND has_table_privilege('authenticated', c.oid, pv.p)) THEN 't' ELSE 'f' END
UNION ALL
SELECT 'service_role_has_no_privilege_on_rtgip_tables|' || CASE WHEN NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace, LATERAL (VALUES ('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) pv(p) WHERE n.nspname IN ('rtgip','rtgip_src','rtgip_fx') AND c.relkind IN ('r','p') AND has_table_privilege('service_role', c.oid, pv.p)) THEN 't' ELSE 'f' END
UNION ALL
SELECT 'anon_has_no_usage_on_rtgip_schemas|' || CASE WHEN NOT EXISTS (SELECT 1 FROM pg_namespace n WHERE n.nspname IN ('rtgip','rtgip_src','rtgip_fx') AND has_schema_privilege('anon', n.oid, 'USAGE')) THEN 't' ELSE 'f' END
UNION ALL
SELECT 'authenticated_has_no_usage_on_rtgip_schemas|' || CASE WHEN NOT EXISTS (SELECT 1 FROM pg_namespace n WHERE n.nspname IN ('rtgip','rtgip_src','rtgip_fx') AND has_schema_privilege('authenticated', n.oid, 'USAGE')) THEN 't' ELSE 'f' END
UNION ALL
SELECT 'service_role_has_no_usage_on_rtgip_schemas|' || CASE WHEN NOT EXISTS (SELECT 1 FROM pg_namespace n WHERE n.nspname IN ('rtgip','rtgip_src','rtgip_fx') AND has_schema_privilege('service_role', n.oid, 'USAGE')) THEN 't' ELSE 'f' END
UNION ALL
SELECT 'every_rtgip_table_has_rls_where_the_package_enables_it|' || CASE WHEN NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE c.relkind = 'r' AND n.nspname = 'rtgip' AND NOT c.relrowsecurity) THEN 't' ELSE 'f' END
UNION ALL
SELECT 'anon_cannot_execute_rtgip_non_trigger_functions|' || CASE WHEN NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname IN ('rtgip','rtgip_src','rtgip_fx') AND p.prorettype <> 'trigger'::regtype AND has_function_privilege('anon', p.oid, 'EXECUTE')) THEN 't' ELSE 'f' END
UNION ALL
SELECT 'authenticated_cannot_execute_rtgip_non_trigger_functions|' || CASE WHEN NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname IN ('rtgip','rtgip_src','rtgip_fx') AND p.prorettype <> 'trigger'::regtype AND has_function_privilege('authenticated', p.oid, 'EXECUTE')) THEN 't' ELSE 'f' END
UNION ALL
SELECT 'service_role_cannot_execute_rtgip_non_trigger_functions|' || CASE WHEN NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname IN ('rtgip','rtgip_src','rtgip_fx') AND p.prorettype <> 'trigger'::regtype AND has_function_privilege('service_role', p.oid, 'EXECUTE')) THEN 't' ELSE 'f' END
UNION ALL
SELECT 'every_security_definer_package_function_pins_search_path|' || CASE WHEN NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE (n.nspname IN ('rtgip','rtgip_src','rtgip_fx') OR n.nspname || '.' || p.proname = ANY (ARRAY['public.apply_payment_estimator_settings','public.integration_apply_event','public.integration_claim_inbox','public.integration_connection_secrets','public.integration_delivery_allowed','public.integration_fail_inbox','public.integration_key_secret','public.integration_quarantine','public.integration_record_source_version','public.integration_replay_inbox','public.repair_items_record_status','public.tenant_store_registry','public.vehicle_history_append_only','public.vehicle_history_apply_identity_correction','public.vehicle_history_audit_write','public.vehicle_history_backfill_tenant','public.vehicle_history_can_read','public.vehicle_history_effective_setting','public.vehicle_history_end_access','public.vehicle_history_flag','public.vehicle_history_flag_reappearance','public.vehicle_history_grant_access','public.vehicle_history_is_manager','public.vehicle_history_is_platform_admin','public.vehicle_history_is_service','public.vehicle_history_next_state','public.vehicle_history_owner_view','public.vehicle_history_record_milestone','public.vehicle_history_resolve_reappearance','public.vehicle_history_set_setting','public.vehicle_history_set_transaction_retention','public.vehicle_instances_custody_guard']::text[])) AND p.prosecdef AND coalesce(array_to_string(p.proconfig, ','), '') NOT LIKE '%search_path=%') THEN 't' ELSE 'f' END
UNION ALL
SELECT 'rtgip_roles_are_nologin_noinherit_nosuper|' || CASE WHEN NOT EXISTS (SELECT 1 FROM pg_roles r WHERE r.rolname LIKE 'rtgip\_%' AND (r.rolcanlogin OR r.rolinherit OR r.rolsuper)) THEN 't' ELSE 'f' END
UNION ALL
SELECT 'anon_has_no_privilege_on_package_public_tables|' || CASE WHEN NOT EXISTS (SELECT 1 FROM unnest(ARRAY['public.vehicles','public.vehicle_instances','public.vehicle_external_refs','public.integration_connections','public.integration_connection_keys','public.integration_inbox','public.integration_source_versions','public.integration_outbox','public.integration_direction_flags','public.inspection_evidence','public.repair_items','public.acquisition_records','public.vehicle_identity_quarantine','public.vehicle_identity_corrections','public.vehicle_custody_milestones','public.service_visits','public.repair_item_status_history','public.vehicle_reappearance_reviews','public.vehicle_access_grants','public.vehicle_history_setting_keys','public.vehicle_history_settings','public.vehicle_history_audit']::text[]) t, LATERAL (VALUES ('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) pv(p) WHERE to_regclass(t) IS NOT NULL AND has_table_privilege('anon', to_regclass(t), pv.p)) THEN 't' ELSE 'f' END
UNION ALL
SELECT 'authenticated_cannot_write_package_public_tables|' || CASE WHEN NOT EXISTS (SELECT 1 FROM unnest(ARRAY['public.vehicles','public.vehicle_instances','public.vehicle_external_refs','public.integration_connections','public.integration_connection_keys','public.integration_inbox','public.integration_source_versions','public.integration_outbox','public.integration_direction_flags','public.inspection_evidence','public.repair_items','public.acquisition_records','public.vehicle_identity_quarantine','public.vehicle_identity_corrections','public.vehicle_custody_milestones','public.service_visits','public.repair_item_status_history','public.vehicle_reappearance_reviews','public.vehicle_access_grants','public.vehicle_history_setting_keys','public.vehicle_history_settings','public.vehicle_history_audit']::text[]) t, LATERAL (VALUES ('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE')) pv(p) WHERE to_regclass(t) IS NOT NULL AND has_table_privilege('authenticated', to_regclass(t), pv.p)) THEN 't' ELSE 'f' END
UNION ALL
SELECT 'package_public_tables_have_rls|' || CASE WHEN NOT EXISTS (SELECT 1 FROM unnest(ARRAY['public.vehicles','public.vehicle_instances','public.vehicle_external_refs','public.integration_connections','public.integration_connection_keys','public.integration_inbox','public.integration_source_versions','public.integration_outbox','public.integration_direction_flags','public.inspection_evidence','public.repair_items','public.acquisition_records','public.vehicle_identity_quarantine','public.vehicle_identity_corrections','public.vehicle_custody_milestones','public.service_visits','public.repair_item_status_history','public.vehicle_reappearance_reviews','public.vehicle_access_grants','public.vehicle_history_setting_keys','public.vehicle_history_settings','public.vehicle_history_audit']::text[]) t WHERE to_regclass(t) IS NOT NULL AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = to_regclass(t))) THEN 't' ELSE 'f' END
UNION ALL
SELECT 'package_policies_are_to_authenticated_only|' || CASE WHEN NOT EXISTS (SELECT 1 FROM pg_policies pp WHERE pp.schemaname || '.' || pp.tablename = ANY (ARRAY['public.vehicles','public.vehicle_instances','public.vehicle_external_refs','public.integration_connections','public.integration_connection_keys','public.integration_inbox','public.integration_source_versions','public.integration_outbox','public.integration_direction_flags','public.inspection_evidence','public.repair_items','public.acquisition_records','public.vehicle_identity_quarantine','public.vehicle_identity_corrections','public.vehicle_custody_milestones','public.service_visits','public.repair_item_status_history','public.vehicle_reappearance_reviews','public.vehicle_access_grants','public.vehicle_history_setting_keys','public.vehicle_history_settings','public.vehicle_history_audit']::text[]) AND pp.roles::text <> '{authenticated}') THEN 't' ELSE 'f' END
UNION ALL
SELECT 'package_policies_wrap_auth_uid_in_select|' || CASE WHEN NOT EXISTS (SELECT 1 FROM pg_policies pp WHERE pp.schemaname || '.' || pp.tablename = ANY (ARRAY['public.vehicles','public.vehicle_instances','public.vehicle_external_refs','public.integration_connections','public.integration_connection_keys','public.integration_inbox','public.integration_source_versions','public.integration_outbox','public.integration_direction_flags','public.inspection_evidence','public.repair_items','public.acquisition_records','public.vehicle_identity_quarantine','public.vehicle_identity_corrections','public.vehicle_custody_milestones','public.service_visits','public.repair_item_status_history','public.vehicle_reappearance_reviews','public.vehicle_access_grants','public.vehicle_history_setting_keys','public.vehicle_history_settings','public.vehicle_history_audit']::text[]) AND pp.qual ~ 'auth\.uid\(\)' AND pp.qual !~ 'SELECT auth\.uid\(\)') THEN 't' ELSE 'f' END
UNION ALL
SELECT 'transport_stays_disabled|' || CASE WHEN to_regclass('rtgip.delivery_config') IS NULL OR (SELECT count(*) FROM rtgip.delivery_config WHERE transport_enabled) = 0 THEN 't' ELSE 'f' END;
